const body = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};

const providedToken = headers['x-publish-token'] || headers['X-Publish-Token'] || body.publishToken || '';
const expectedToken = $env.PUBLISH_SECRET || '';

if (!expectedToken) {
  throw new Error('PUBLISH_SECRET environment variable is not set');
}

if (providedToken !== expectedToken) {
  return [{
    json: {
      authorized: false,
      lessonID: null,
      error: 'Invalid or missing X-Publish-Token header'
    }
  }];
}

const lessonID = body.lesson_id || body.lessonID;
if (!lessonID) {
  return [{
    json: {
      authorized: false,
      lessonID: null,
      error: 'Missing required field: lesson_id'
    }
  }];
}

return [{
  json: {
    authorized: true,
    lessonID
  }
}];

const lesson = $input.first().json;

// Parse lesson_id format: M##-W##-L##
const match = lesson.lesson_id.match(/^M(\d+)-W(\d+)-L(\d+)$/i);
if (!match) {
  throw new Error(`Invalid lesson_id format: ${lesson.lesson_id}. Expected M##-W##-L##`);
}

const month = parseInt(match[1]);
const week = parseInt(match[2]);
const lessonNum = parseInt(match[3]);

// Build course code from month
const monthPadded = String(month).padStart(2, '0');
const courseCode = `M${monthPadded}-COURSE`;
const courseTitle = `Month ${month}: ${getCourseTitle(month)}`;

function getCourseTitle(m) {
  const titles = {
    1: 'Recruiting Foundations',
    2: 'Sourcing Mastery',
    3: 'Candidate Experience',
    4: 'Interview Excellence',
    5: 'Offer & Negotiation',
    6: 'Onboarding Strategy',
    7: 'Data-Driven Recruiting',
    8: 'Employer Brand',
    9: 'Executive Search',
    10: 'Talent Intelligence',
    11: 'Strategic Workforce Planning',
    12: 'Leadership & Influence'
  };
  return titles[m] || `Month ${m} Content`;
}

// Position in the LMS = (week - 1) * lessons_per_week + lesson_num
// Use a flat position for simplicity: sequential within the course
const position = ((week - 1) * 5) + lessonNum;

return [{
  json: {
    ...lesson,
    parsedMonth: month,
    parsedWeek: week,
    parsedLessonNum: lessonNum,
    courseCode,
    courseTitle,
    modulePosition: position,
    moduleTitle: `Week ${week}, Lesson ${lessonNum}: ${(lesson.hook || '').slice(0, 60)}${lesson.hook && lesson.hook.length > 60 ? '...' : ''}`
  }
}];
